/**
 * Types and accessors for the station weighbridge aggregates.
 * -------------------------------------------------------------------------
 * The data in `src/data/weighbridge.json` is generated by
 * `scripts/ingest-weighbridge.mjs` from raw operator exports. It holds
 * aggregates only — no account numbers, no licence plates — so it is safe to
 * commit. See `meta.excluded` for exactly what the ingest dropped.
 *
 * This is a *different source* from the EPD/CSDI facility data: EPD publishes
 * no per-facility throughput, whereas these are measured per-weigh-in records
 * from the station's own weighbridge. Keep the two clearly labelled apart.
 */
import RAW from "@/data/weighbridge.json";

/** A station's daily intake. `private + public + gtw` equals `tonnes`. */
export interface WeighbridgeDay {
  /** ISO date, `YYYY-MM-DD`. */
  date: string;
  tonnes: number;
  loads: number;
  private: number;
  public: number;
  gtw: number;
}

/** Who delivers the waste. `share` is of received tonnage, not of loads. */
export interface WeighbridgeStream {
  key: "private" | "public" | "gtw" | "other";
  labelEn: string;
  labelZh: string;
  tonnes: number;
  loads: number;
  share: number;
}

export interface WeighbridgeWasteType {
  /** EPD waste classification code, e.g. `S40.00`. */
  code: string;
  nameZh: string;
  nameEn: string;
  /** Domestic / Commercial / Industrial / Special / Other. */
  group: string;
  tonnes: number;
  loads: number;
  /** True for grease trap waste — WKTS is the only station that takes it. */
  gtw: boolean;
}

export interface WeighbridgeDistrict {
  /** Operator's source code, e.g. `31`. */
  code: string;
  nameZh: string;
  nameEn: string;
  tonnes: number;
  loads: number;
}

export interface WeighbridgeVehicleTask {
  /** Raw task label from the export, e.g. `P99 私人車傾倒`. */
  task: string;
  stream: string;
  tonnes: number;
  loads: number;
}

export interface WeighbridgeStation {
  stationId: string;
  /** Joins to `FacilityProperties.id` in `src/data/waste-facilities.ts`. */
  facilityId: string;
  period: { from: string; to: string; operatingDays: number };
  totals: {
    /** Received waste only — excludes the station's own maintenance loads. */
    tonnes: number;
    loads: number;
    tonnesPerDay: number;
    maintenanceTonnes: number;
    maintenanceLoads: number;
  };
  daily: WeighbridgeDay[];
  streams: WeighbridgeStream[];
  vehicleTasks: WeighbridgeVehicleTask[];
  wasteTypes: WeighbridgeWasteType[];
  /** Only the maintenance vehicle's loads, which never count as intake. */
  wasteTypesMaintenance: Array<{
    code: string;
    nameZh: string;
    nameEn: string;
    tonnes: number;
    loads: number;
  }>;
  districts: WeighbridgeDistrict[];
}

export interface WeighbridgeMeta {
  source: string;
  sourceZh: string;
  /** Only weigh-ins with this 交收狀態 are counted. */
  statusKept: string;
  generatedAt: string;
  sourceFiles: string[];
  stations: string[];
  excluded: {
    notCompletedRecords: number;
    notCompletedTonnes: number;
    notCompletedByStatus: Record<string, number>;
    unparseableWeight: number;
    unknownStation: number;
    noteEn: string;
    noteZh: string;
  };
  warnings?: string[];
}

export interface WeighbridgeDataset {
  meta: WeighbridgeMeta;
  stations: Record<string, WeighbridgeStation>;
}

export const WEIGHBRIDGE_DATA = RAW as unknown as WeighbridgeDataset;

/** Station ids that have weighbridge coverage, sorted. */
export const WEIGHBRIDGE_STATION_IDS = Object.keys(WEIGHBRIDGE_DATA.stations).sort();

/** Facility ids (as used by the map) that have weighbridge coverage. */
export const WEIGHBRIDGE_FACILITY_IDS = new Set(
  Object.values(WEIGHBRIDGE_DATA.stations).map((s) => s.facilityId)
);

/** Records for a station, looked up by its map facility id. */
export function findStationRecordsByFacilityId(
  facilityId: string
): WeighbridgeStation | null {
  for (const station of Object.values(WEIGHBRIDGE_DATA.stations)) {
    if (station.facilityId === facilityId) return station;
  }
  return null;
}

/** Records for a station, looked up by its operator station code (e.g. WKTS). */
export function findStationRecords(stationId: string): WeighbridgeStation | null {
  return WEIGHBRIDGE_DATA.stations[stationId.toUpperCase()] ?? null;
}
